solution.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        if (in.hasNextLong()) {
            long cac = in.nextLong();
            long foyda = in.nextLong();
            System.out.println((cac + foyda - 1) / foyda);
        }
    }
}

